// Synthetic native-provider motion regression: node skin_motion_journey.cjs after zoom 390 light.
// AGENTNET_SKIN_WORLD / AGENTNET_COMPANY_BINARY must name the disposable company fixture.
// AGENTNET_MOTION_EVIDENCE selects temporary video/probe/screenshot output; never commit it.
// REDUCED=1 runs the same interaction assertions with reduced motion.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const {execFile}=require('node:child_process');
const {chromium}=require(process.env.AGENTNET_PLAYWRIGHT||'playwright-core');
const [phase,skin,ws,theme]=process.argv.slice(2),width=+ws,height=1000;
const base=path.resolve(process.env.AGENTNET_MOTION_EVIDENCE||'/tmp/agentnet-skins-motion-evidence'),world=path.resolve(process.env.AGENTNET_SKIN_WORLD||base+'/world'),dir=`${base}/${phase}/${skin}-${width}-${theme}`;
fs.mkdirSync(dir,{recursive:true,mode:0o700});
const urls=JSON.parse(fs.readFileSync(world+'/urls.json')),seed=JSON.parse(fs.readFileSync(world+'/seed.json'));
const origin=new URL(urls.sergey.page);assert.equal(origin.hostname,'127.0.0.1');assert.notEqual(origin.port,'18990');
const log={phase,skin,width,height,theme,steps:[],syncs:[],errors:[],checks:[]};let browser,context,page;
function probe(){const sr=document.querySelector('#skin').shadowRoot;for(const type of ['click','input','keydown'])sr.addEventListener(type,()=>{if(window.__actionWall===null)window.__actionWall=Date.now()},true);let frames=[],events=[],raf=0,start=0;const ids=new WeakMap();let seq=0;const id=x=>{if(!ids.has(x))ids.set(x,++seq);return ids.get(x)};
for(const type of ['animationstart','animationend','animationcancel'])sr.addEventListener(type,e=>events.push({type,name:e.animationName,t:performance.now()-start}),true);
window.__probe={start(){window.__actionWall=null;frames=[];events=[];start=performance.now();const sample=()=>{const z=sr.querySelector('#zoom');const a=sr.activeElement;frames.push({t:performance.now()-start,focus:a?.id||a?.className||null,dialog:!!sr.querySelector('dialog[open]'),layers:z?[...z.children].map(l=>{const s=getComputedStyle(l),c=l.querySelector('.zoom-content');return{id:id(l),opacity:+s.opacity,scale:s.transform==='none'?1:new DOMMatrixReadOnly(s.transform).a,origin:s.transformOrigin,level:[...l.querySelectorAll('.rung')].findIndex(x=>x.classList.contains('here')),scroll:c?.scrollTop}}):[],section:sr.querySelector('#section-title')?.textContent,title:sr.querySelector('#conv-name')?.textContent,conv:sr.querySelector('.classic-root')?.classList.contains('show-conv')});raf=requestAnimationFrame(sample)};sample();return Date.now()},stop(){cancelAnimationFrame(raf);return{frames,events}}}}
async function sync(){return page.evaluate(()=>new Promise(r=>{const d=document.createElement('div');d.style.cssText='position:fixed;left:0;top:0;width:32px;height:32px;background:#ff00ff;z-index:2147483647';document.documentElement.append(d);requestAnimationFrame(()=>requestAnimationFrame(()=>{const t=Date.now();setTimeout(()=>{d.remove();r(t)},400)}))}))}
async function step(label,action){let wall=await page.evaluate(()=>window.__probe.start());await action();wall=await page.evaluate(()=>window.__actionWall)||wall;await page.waitForTimeout(950);const p=await page.evaluate(()=>window.__probe.stop());log.steps.push({label,wall,probe:p});await page.screenshot({path:dir+'/'+label+'.png'});console.log('recorded '+skin+' '+width+' '+theme+' '+label)}
const Z=s=>page.locator('#zoom .zoom-layer:last-child '+s);
async function level(){return page.evaluate(()=>[...document.querySelector('#skin').shadowRoot.querySelectorAll('#zoom .zoom-layer:last-child .rung')].findIndex(x=>x.classList.contains('here')))}
async function check(name,ok){log.checks.push({name,pass:!!ok});if(phase==='after')assert(ok,name)}
async function sendUnread(){await new Promise((r,j)=>execFile(process.env.AGENTNET_COMPANY_BINARY||base+'/agentnet',['--home',world+'/vitalii','dm','send',seed.dm_vitalii,'Motion refresh '+phase+' '+width+' '+theme],{env:{...process.env,HOME:world+'/cli-home',PATH:world+'/bin:/usr/bin:/bin',SSL_CERT_FILE:world+'/cert.pem',AGENTNET_NOTIFY:'off'},timeout:15000},e=>e?j(e):r()))}
(async()=>{browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox']});context=await browser.newContext({viewport:{width,height},colorScheme:theme,reducedMotion:process.env.REDUCED?'reduce':'no-preference',recordVideo:{dir,size:{width,height}}});page=await context.newPage();await page.addInitScript(()=>{window.__unstyledBars=[];const sample=()=>{const h=document.querySelector('#skin-bar'),nav=h?.shadowRoot?.querySelector('nav');if(nav&&getComputedStyle(nav).visibility!=='hidden'&&!h.shadowRoot.querySelector('link[rel=stylesheet]')?.sheet)window.__unstyledBars.push(performance.now());requestAnimationFrame(sample)};requestAnimationFrame(sample)});page.setDefaultTimeout(15000);page.on('pageerror',e=>log.errors.push(e.message));await page.goto(urls.sergey.page);const u=new URL(origin.origin);u.searchParams.set('skin',skin);await page.goto(u.href);await page.locator('.'+skin+'-root').waitFor();await page.locator('#profile-btn').click();await page.locator('#settings-tab-appearance').click();await page.locator('[data-theme="'+theme+'"]').first().click();await page.locator('#settings-close').click();await page.waitForTimeout(1800);await page.evaluate(probe);log.syncs.push(await sync());
if(skin==='zoom'){
const everyone=async()=>{if(await level())await Z('.rung').nth(0).click();await Z('.person-card').filter({hasText:'Vitalii'}).waitFor();await page.waitForTimeout(600)};
const person=()=>Z('.person-card').filter({hasText:'Vitalii'}).click();
const dm=()=>Z('.thread-list[aria-label="DMs with Vitalii"] button').filter({hasText:'Harbor Inn'}).first().click();
await everyone();await step('01-person-spatial',person);await sendUnread();await page.waitForTimeout(600);await step('02-unread-dm-spatial',dm);const spatial=log.steps.at(-1).probe;await check('background refresh preserves full spatial animation',process.env.REDUCED||(()=>{const f=spatial.frames.filter(f=>f.layers.length===2);return f.length>1&&f.at(-1).t-f[0].t>=400&&spatial.events.some(e=>e.type==='animationstart'&&e.name.startsWith('zArrive'))})());await check('old and incoming text never overlap',spatial.frames.every(f=>f.layers.length!==2||f.layers.some(l=>l.opacity<0.025)));
await step('03-write-open',()=>Z('.zoom-write button').click());await page.locator('#write-body').fill('Motion send '+phase+' '+width+' '+theme);await step('04-send',()=>page.locator('#dialog-ok').click());
await check('sent message visible',await Z('.mc-text').getByText('Motion send '+phase+' '+width+' '+theme,{exact:true}).last().evaluate(e=>{const c=e.closest('.zoom-content').getBoundingClientRect(),b=e.getBoundingClientRect();return b.top>=c.top&&b.bottom<=c.bottom}));
await step('05-escape-after-send',()=>page.keyboard.press('Escape'));await check('Escape after send zooms out',await level()===1);if(await level()!==1)await Z('.rung').nth(1).click();await page.waitForTimeout(600);await dm();await page.waitForTimeout(600);
await Z('.mc-bubble').filter({hasText:'pallets.png'}).click();await page.waitForFunction(()=>{const z=document.querySelector('#skin').shadowRoot.querySelector('#zoom');return z.children.length===1&&z.querySelector('.zoom-message')&&!z.getAnimations({subtree:true}).some(a=>a.playState==='running')});const imageRect=await Z('.zoom-message').boundingBox();await step('06-image-open',()=>Z('.file').filter({hasText:'pallets.png'}).getByRole('button',{name:'Open',exact:true}).click());log.imageGeometry={before:imageRect,after:await Z('.zoom-message').boundingBox()};await check('image does not change underlying message geometry',Math.abs(log.imageGeometry.before.height-log.imageGeometry.after.height)<1);await step('07-escape-image',()=>page.keyboard.press('Escape'));await check('Escape after image changes owned view',await level()===2||log.steps.at(-1).probe.frames[0].dialog&&!log.steps.at(-1).probe.frames.at(-1).dialog);if(await level()===3){await page.keyboard.press('Escape');await page.waitForTimeout(650)}await check('Escape leaves message after preview closes',await level()===2);await page.waitForTimeout(600);await everyone();
await step('08-devices-expand',()=>Z('.person-devices summary').filter({hasText:'Vitalii on'}).click());const deviceBox=await Z('.person-devices[open] .device-list button').first().boundingBox();await step('09-device-origin',()=>Z('.person-devices[open] .device-list button').first().click());const deviceFrame=log.steps.at(-1).probe.frames.find(f=>f.layers.length===2)?.layers.at(-1),deviceArea=await page.locator('#zoom').boundingBox();await check('device origin is clicked row',process.env.REDUCED||deviceFrame&&Math.abs(parseFloat(deviceFrame.origin)-(deviceBox.x+deviceBox.width/2-deviceArea.x))<3);await everyone();
await step('10-search-results',()=>Z('.zoom-search').fill('Bohdan'));const result=Z('.result').filter({hasText:'PersonBohdan'}).first();const box=await result.boundingBox();await step('11-search-origin',()=>result.click());const last=log.steps.at(-1).probe.frames.find(f=>f.layers.length===2)?.layers.at(-1);const zr=await page.locator('#zoom').boundingBox();await check('search origin is clicked row',process.env.REDUCED||last&&Math.abs(parseFloat(last.origin)-(box.x+box.width/2-zr.x))<3);await everyone();await Z('button').filter({hasText:'Savannah rush order'}).first().click();await page.waitForTimeout(650);await step('12-group-summary',()=>page.keyboard.press('Escape'));await check('group summary dates valid',!await Z('.zoom-content').innerText().then(s=>s.includes('Invalid Date')));
await check('no whole-area focus outline',await page.evaluate(()=>{const s=document.querySelector('#skin').shadowRoot,z=s.querySelector('#zoom');return s.activeElement!==z||getComputedStyle(z).outlineStyle==='none'}));
}else{
await step('01-reload',async()=>{await page.reload();await page.locator('.classic-root').waitFor();await page.evaluate(probe)});await check('reload has no unstyled host controls',await page.evaluate(()=>window.__unstyledBars.length===0));
// The reload recreates the probe; this step's exact video timing remains in the log.
if(width<761){for(let i=0;i<4&&!await page.locator('#nav-people').isVisible();i++){await page.locator('#back').click();await page.waitForTimeout(300)}}await page.locator('#nav-people').click();await page.locator('#conv-list .conv-item.contact').filter({hasText:'Vitalii'}).first().click();await page.waitForTimeout(600);
// With two DMs, the person hub is intentional; choose the Harbor Inn row.
if(await page.locator('#hub:visible').count())await page.locator('#hub .thread-row').filter({hasText:'Harbor Inn'}).first().click();await page.waitForTimeout(700);
await page.locator('#timeline .file').filter({hasText:'pallets.png'}).getByRole('button',{name:'Open',exact:true}).scrollIntoViewIfNeeded();await page.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));const timelineHeight=await page.locator('#timeline').evaluate(e=>e.scrollHeight);await step('02-image-open',()=>page.locator('#timeline .file').filter({hasText:'pallets.png'}).getByRole('button',{name:'Open',exact:true}).click());await check('preview keeps chat geometry',await page.locator('#timeline').evaluate(e=>e.scrollHeight)===timelineHeight);await step('03-image-escape',()=>page.keyboard.press('Escape'));
await check('preview restores file opener focus',await page.evaluate(()=>document.querySelector('#skin').shadowRoot.activeElement?.dataset?.fileOpen!==undefined));if(width<761){await page.locator('#back').click();await page.waitForTimeout(500);if(await page.locator('#hub:visible').count())await page.locator('#back').click();}
await page.locator('#nav-chats').click();await step('04-mobile-dm-commit',()=>page.locator('#conv-list .conv-item.contact').filter({hasText:'Bohdan'}).first().click());if(width<761)await check('no stale phone pane before DM commit',log.steps.at(-1).probe.frames.every(f=>!f.conv||f.title==='Bohdan'));if(width<761){await step('05-direct-back',()=>page.locator('#back').click());await check('direct list DM uses one Back',!await page.locator('.classic-root').evaluate(e=>e.classList.contains('show-conv')))}
if(width<761){for(let i=0;i<4&&!await page.locator('#review-btn').isVisible();i++){await page.locator('#back').click();await page.waitForTimeout(300)}}await page.locator('#review-btn').click();await page.locator('#review-list button').first().waitFor();await step('06-activity-open',()=>page.locator('#review-list button').first().click());const activity=log.steps.at(-1).probe.frames;const initialTitle=activity[0].title;await check('Activity sidebar and destination commit together',activity.every(f=>f.section==='Activity'||f.title!==initialTitle||initialTitle===activity.at(-1).title));if(width<761){await step('07-activity-back',()=>page.locator('#back').click());await check('Activity uses one Back and returns to Activity',await page.locator('#section-title').innerText()==='Activity'&&!await page.locator('.classic-root').evaluate(e=>e.classList.contains('show-conv')))}
}
log.syncs.push(await sync());await check('no browser exceptions',!log.errors.length);await context.close();log.video=await page.video().path();fs.writeFileSync(dir+'/log.json',JSON.stringify(log,null,2));await browser.close();console.log('DONE '+dir)} )().catch(async e=>{log.failure=e.message;try{await context?.close();log.video=await page?.video()?.path()}catch{}fs.writeFileSync(dir+'/log.json',JSON.stringify(log,null,2));await browser?.close();console.error(e.message);process.exitCode=1});
